import java.io.IOException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import org.json.JSONObject;
import org.json.JSONArray;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String fiscal = req.getParameter("fiscal_year");

        if (department == null || department.isEmpty()) {
            resp.sendError(400, "dept parameter required");
            return;
        }

        // Validate fiscal year format
        if (fiscal != null && !fiscal.matches("\\d{4}")) {
            resp.sendError(400, "Invalid fiscal year");
            return;
        }

        // Sort column whitelist - looks secure but sortCol used elsewhere
        String[] allowedSorts = {"created_at", "amount", "status", "report_id"};
        String safeSort = "created_at";
        if (sortCol != null) {
            for (String allowed : allowedSorts) {
                if (allowed.equals(sortCol)) {
                    safeSort = sortCol;
                    break;
                }
            }
        }

        // Build query - department is concatenated directly
        String query = "SELECT r.report_id, r.title, r.amount, r.status, "
                     + "r.created_at, u.full_name "
                     + "FROM expense_reports r "
                     + "JOIN users u ON r.submitter_id = u.user_id "
                     + "WHERE r.department = '" + department + "' ";

        if (fiscal != null) {
            query += "AND EXTRACT(YEAR FROM r.created_at) = " + fiscal + " ";
        }

        query += "ORDER BY r." + safeSort + " DESC LIMIT 200";

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("report_id", rs.getInt("report_id"));
                row.put("title", rs.getString("title"));
                row.put("amount", rs.getDouble("amount"));
                row.put("status", rs.getString("status"));
                row.put("created_at", rs.getString("created_at"));
                row.put("submitter", rs.getString("full_name"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Log full error for debugging - also a concern
            resp.setStatus(500);
            JSONObject err = new JSONObject();
            err.put("error", "Database query failed");
            err.put("detail", e.getMessage());
            resp.setContentType("application/json");
            resp.getWriter().write(err.toString());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Stub for report submission - uses PreparedStatement (safe)
        resp.sendError(501, "Not implemented");
    }
}
